"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { ChatCircleTextIcon, GearIcon } from "@phosphor-icons/react/dist/ssr"

import { cn } from "@/lib/utils"

const TABS = [
  { href: "/templates/chat", label: "대화", icon: ChatCircleTextIcon },
  { href: "/templates/chat/settings", label: "설정", icon: GearIcon },
] as const

/** Chat 템플릿 내부 탭 — 대화 화면/설정 화면 전환. */
export function ChatNav() {
  const pathname = usePathname()

  return (
    <nav aria-label="Chat 템플릿 내비게이션" className="flex w-fit items-center gap-1 rounded-lg border border-border bg-card p-1">
      {TABS.map(({ href, label, icon: Icon }) => {
        const active = pathname === href
        return (
          <Link
            key={href}
            href={href}
            aria-current={active ? "page" : undefined}
            className={cn(
              "flex items-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition-colors",
              active
                ? "bg-primary text-primary-foreground"
                : "text-muted-foreground hover:bg-muted hover:text-foreground",
            )}
          >
            <Icon size={14} weight={active ? "duotone" : "regular"} />
            {label}
          </Link>
        )
      })}
    </nav>
  )
}

"use client"

import { useState } from "react"

import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet"
import type { ChatMessage, Conversation } from "../_lib/data"
import { ChatMain } from "./chat-main"
import { ConversationList } from "./conversation-list"

interface ChatShellProps {
  conversations: Conversation[]
  messages: ChatMessage[]
  defaultConversationId: string
}

/**
 * 대화 화면 조합 — 데스크톱은 대화목록(좌) + 대화창(우) 2컬럼(사이트 전역
 * SiteSidebar 와 합쳐지면 3분할), 모바일은 대화창 단일 컬럼 + 대화목록을
 * 담은 Sheet 드로어로 반응형 전환한다.
 */
export function ChatShell({ conversations, messages, defaultConversationId }: Readonly<ChatShellProps>) {
  const [selectedId, setSelectedId] = useState(defaultConversationId)
  const [sheetOpen, setSheetOpen] = useState(false)

  const conversation = conversations.find((item) => item.id === selectedId)
  const conversationMessages = messages.filter((message) => message.conversationId === selectedId)

  function selectConversation(id: string) {
    setSelectedId(id)
    setSheetOpen(false)
  }

  return (
    <div className="flex h-full min-h-0 gap-4">
      <aside className="hidden w-72 shrink-0 lg:flex">
        <ConversationList conversations={conversations} selectedId={selectedId} onSelect={selectConversation} className="w-full" />
      </aside>

      <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
        <SheetContent side="left" className="w-72">
          <SheetHeader>
            <SheetTitle>대화 목록</SheetTitle>
          </SheetHeader>
          <ConversationList
            conversations={conversations}
            selectedId={selectedId}
            onSelect={selectConversation}
            className="min-h-0 flex-1 px-4 pb-4"
          />
        </SheetContent>
      </Sheet>

      <div className="min-h-0 min-w-0 flex-1">
        <ChatMain
          key={selectedId}
          conversation={conversation}
          initialMessages={conversationMessages}
          onOpenConversationList={() => setSheetOpen(true)}
        />
      </div>
    </div>
  )
}

"use client"

import { useId, useState } from "react"
import { FilePdfIcon, ImageIcon, PaperPlaneRightIcon, PaperclipIcon, TableIcon, XIcon } from "@phosphor-icons/react/dist/ssr"

import {
  Attachment,
  AttachmentAction,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentGroup,
  AttachmentMedia,
  AttachmentTitle,
} from "@/components/ui/attachment"
import { InputGroup, InputGroupAddon, InputGroupButton, InputGroupTextarea } from "@/components/ui/input-group"
import type { MessageAttachment } from "../_lib/data"

const ATTACHMENT_KIND_ICON = {
  pdf: FilePdfIcon,
  image: ImageIcon,
  sheet: TableIcon,
} as const

/** 첨부 버튼을 누르면 순환으로 붙는 데모용 샘플 파일 — 실제 업로드는 하지 않는다. */
const SAMPLE_ATTACHMENTS: MessageAttachment[] = [
  { id: "sample-pdf", name: "회의록_요약.pdf", size: "184KB", kind: "pdf" },
  { id: "sample-image", name: "화면_캡처.png", size: "620KB", kind: "image" },
  { id: "sample-sheet", name: "지표_정리.xlsx", size: "96KB", kind: "sheet" },
]

interface ComposerProps {
  onSend: (draft: { text: string; attachments: MessageAttachment[] }) => void
}

/** 대화창 하단 입력창 — 텍스트 + 첨부(attachment) 버튼, 전송 버튼으로 구성된다. */
export function Composer({ onSend }: Readonly<ComposerProps>) {
  const [text, setText] = useState("")
  const [attachments, setAttachments] = useState<MessageAttachment[]>([])
  const textareaId = useId()

  const canSend = text.trim().length > 0 || attachments.length > 0

  function addSampleAttachment() {
    const next = SAMPLE_ATTACHMENTS.find((sample) => !attachments.some((a) => a.id === sample.id))
    if (!next) return
    setAttachments((prev) => [...prev, next])
  }

  function removeAttachment(id: string) {
    setAttachments((prev) => prev.filter((attachment) => attachment.id !== id))
  }

  function submitDraft() {
    if (!canSend) return
    onSend({ text: text.trim(), attachments })
    setText("")
    setAttachments([])
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    submitDraft()
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-2 border-t border-border pt-3">
      {attachments.length > 0 && (
        <AttachmentGroup>
          {attachments.map((attachment) => {
            const Icon = ATTACHMENT_KIND_ICON[attachment.kind]
            return (
              <Attachment key={attachment.id} size="sm" state="done">
                <AttachmentMedia>
                  <Icon size={16} weight="regular" />
                </AttachmentMedia>
                <AttachmentContent>
                  <AttachmentTitle>{attachment.name}</AttachmentTitle>
                  <AttachmentDescription>{attachment.size}</AttachmentDescription>
                </AttachmentContent>
                <AttachmentActions>
                  <AttachmentAction aria-label={`${attachment.name} 첨부 제거`} onClick={() => removeAttachment(attachment.id)}>
                    <XIcon size={12} weight="regular" />
                  </AttachmentAction>
                </AttachmentActions>
              </Attachment>
            )
          })}
        </AttachmentGroup>
      )}
      <InputGroup>
        <InputGroupAddon align="block-start">
          <InputGroupButton
            type="button"
            size="icon-xs"
            aria-label="파일 첨부"
            onClick={addSampleAttachment}
            disabled={attachments.length >= SAMPLE_ATTACHMENTS.length}
          >
            <PaperclipIcon size={14} weight="regular" />
          </InputGroupButton>
        </InputGroupAddon>
        <InputGroupTextarea
          id={textareaId}
          placeholder="메시지를 입력하세요…"
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault()
              submitDraft()
            }
          }}
        />
        <InputGroupAddon align="block-end" className="justify-end">
          <InputGroupButton type="submit" size="icon-xs" aria-label="메시지 보내기" disabled={!canSend}>
            <PaperPlaneRightIcon size={14} weight="regular" />
          </InputGroupButton>
        </InputGroupAddon>
      </InputGroup>
    </form>
  )
}

"use client"

import { PlusIcon, PushPinIcon } from "@phosphor-icons/react/dist/ssr"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import type { Conversation } from "../_lib/data"

interface ConversationListProps {
  conversations: Conversation[]
  selectedId: string
  onSelect: (id: string) => void
  className?: string
}

/**
 * 좌측 대화목록 — 데스크톱에서는 chat-shell.tsx 가 상시 노출 컬럼으로,
 * 모바일에서는 같은 컴포넌트를 Sheet 안에 그대로 넣어 재사용한다.
 */
export function ConversationList({ conversations, selectedId, onSelect, className }: Readonly<ConversationListProps>) {
  const pinned = conversations.filter((conversation) => conversation.pinned)
  const rest = conversations.filter((conversation) => !conversation.pinned)

  return (
    <div className={cn("flex h-full min-h-0 flex-col gap-3", className)}>
      <Button type="button" variant="outline" size="sm" className="justify-start" onClick={() => onSelect("new-chat")}>
        <PlusIcon size={14} weight="regular" />
        새 대화
      </Button>
      <ul className="flex min-h-0 flex-1 flex-col gap-1 overflow-y-auto">
        {pinned.length > 0 && (
          <li aria-hidden className="px-2 pt-1 pb-0.5 text-xs font-medium text-muted-foreground">
            고정됨
          </li>
        )}
        {pinned.map((conversation) => (
          <ConversationRow
            key={conversation.id}
            conversation={conversation}
            active={conversation.id === selectedId}
            onSelect={onSelect}
          />
        ))}
        {rest.length > 0 && (
          <li aria-hidden className="px-2 pt-3 pb-0.5 text-xs font-medium text-muted-foreground">
            모든 대화
          </li>
        )}
        {rest.map((conversation) => (
          <ConversationRow
            key={conversation.id}
            conversation={conversation}
            active={conversation.id === selectedId}
            onSelect={onSelect}
          />
        ))}
      </ul>
    </div>
  )
}

function ConversationRow({
  conversation,
  active,
  onSelect,
}: Readonly<{
  conversation: Conversation
  active: boolean
  onSelect: (id: string) => void
}>) {
  return (
    <li>
      <button
        type="button"
        aria-current={active ? "page" : undefined}
        onClick={() => onSelect(conversation.id)}
        className={cn(
          "flex w-full flex-col gap-0.5 rounded-md px-2.5 py-2 text-left transition-colors",
          active ? "bg-primary text-primary-foreground" : "text-foreground hover:bg-muted",
        )}
      >
        <span className="flex items-center gap-1.5 text-sm font-medium">
          {conversation.pinned && (
            <PushPinIcon size={12} weight="fill" className={active ? "text-primary-foreground" : "text-muted-foreground"} />
          )}
          <span className="min-w-0 flex-1 truncate">{conversation.title}</span>
          {conversation.unread && !active && (
            <Badge variant="default" className="size-1.5 shrink-0 rounded-full p-0" aria-label="읽지 않음" />
          )}
        </span>
        <span
          className={cn(
            "flex items-center justify-between gap-2 text-xs",
            active ? "text-primary-foreground/80" : "text-muted-foreground",
          )}
        >
          <span className="min-w-0 flex-1 truncate">{conversation.preview}</span>
          <span className="shrink-0">{conversation.updatedAt}</span>
        </span>
      </button>
    </li>
  )
}
